//! The licenses of what the app ships: Starling's own, and the third-party
//! notices build.rs embeds (generated by scripts/licenses/notices.py, the
//! same schema the Android app builds in Gradle).

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// Starling's own license text, always present.
pub const STARLING_LICENSE: &str = include_str!("../../../../../LICENSE");

const EMBEDDED: &str = include_str!(concat!(env!("OUT_DIR"), "/third-party-notices.json"));

#[derive(Debug, Deserialize)]
pub struct Notices {
    /// Sorted by name.
    pub components: Vec<Component>,
    texts: HashMap<String, String>,
}

#[derive(Debug, Deserialize)]
pub struct Component {
    pub name: String,
    pub version: String,
    /// An SPDX expression, e.g. "MIT OR Apache-2.0".
    pub license: String,
    pub url: String,
    texts: Vec<String>,
}

impl Notices {
    /// The license texts of `component`, in the order it lists them.
    pub fn texts<'a>(&'a self, component: &'a Component) -> impl Iterator<Item = &'a str> + 'a {
        component
            .texts
            .iter()
            .filter_map(|key| self.texts.get(key).map(String::as_str))
    }
}

/// The embedded notices, or `None` in a development build that never
/// generated them.
pub fn notices() -> Option<&'static Notices> {
    static NOTICES: OnceLock<Option<Notices>> = OnceLock::new();
    NOTICES.get_or_init(|| parse(EMBEDDED)).as_ref()
}

fn parse(json: &str) -> Option<Notices> {
    // A malformed file is a packaging bug; the page then reads like a
    // development build rather than taking the settings sheet down.
    serde_json::from_str::<Option<Notices>>(json).ok().flatten()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn components_resolve_their_texts() {
        let notices = parse(
            r#"{"schema":1,"app":"desktop","targets":["x86_64-unknown-linux-gnu"],
                "starling":{"license":"MIT","text":"a"},
                "components":[{"name":"serde","version":"1.0.0","license":"MIT OR Apache-2.0",
                               "url":"https://serde.rs","texts":["a","b","missing"]}],
                "texts":{"a":"MIT text","b":"Apache text"}}"#,
        )
        .expect("notices");
        let serde = &notices.components[0];
        assert_eq!(
            notices.texts(serde).collect::<Vec<_>>(),
            ["MIT text", "Apache text"]
        );
    }

    #[test]
    fn a_development_build_has_no_notices() {
        assert!(parse("null").is_none());
        assert!(parse("not json").is_none());
    }

    #[test]
    fn starlings_own_license_is_embedded() {
        assert!(STARLING_LICENSE.starts_with("MIT License"));
    }
}
